/** Backs up old storage and transforms persisted state without dropping its records. */
function migratePersistedState(persisted: unknown, version: number): Partial<FinanceState> {
  const value = persisted && typeof persisted === 'object' ? persisted as Record<string, unknown> : {}
  const report: string[] = []
  if (version < 3) {
    try {
      const stored = localStorage.getItem('moneyflow-data-v1')
      if (stored) localStorage.setItem(`moneyflow-migration-backup-${Date.now()}`, stored)
    } catch {
      report.push('The automatic pre-migration backup could not be written. Existing records were retained in place.')
    }
    if (['transactions', 'budgets', 'goals', 'dailyBudgets', 'contributions'].some((key) => Array.isArray(value[key]) && (value[key] as unknown[]).length)) report.push('MoneyFlow data schema upgraded. Existing transactions, budgets, goals, daily budgets, and contributions were preserved.')
  }

  const transactions = Array.isArray(value.transactions) ? value.transactions as Transaction[] : []
  const budgets = Array.isArray(value.budgets) ? value.budgets as Budget[] : []
  const goals = Array.isArray(value.goals) ? value.goals as Goal[] : []
  const dailyBudgets = Array.isArray(value.dailyBudgets) ? value.dailyBudgets as DailyBudget[] : []
  const defaultAccountId = 'account-default-cash'
  let accounts = Array.isArray(value.accounts) ? value.accounts as Account[] : []
  const needsDefaultAccount = transactions.some((transaction) => transaction.type !== 'saving' && !transaction.accountId)
  if (!accounts.length && transactions.length || needsDefaultAccount) {
    if (!accounts.some((account) => account.id === defaultAccountId)) {
    accounts = [...accounts, { id: defaultAccountId, name: 'Primary account', institution: 'Cash and legacy activity', kind: 'Cash', openingBalance: 0, includeInTotal: true, archived: false, color: '#3ba7ff', icon: 'wallet', nickname: '' }]
    }
    for (const transaction of transactions) if (transaction.type !== 'saving') transaction.accountId ??= defaultAccountId
    report.push('A Primary account was created and assigned to legacy transactions without an account.')
  }
  if (accounts.length && !Array.isArray(value.accounts)) report.push('Existing transactions now use a default account; review its opening balance in Accounts.')
  const profile = value.profile && typeof value.profile === 'object' ? { ...defaultProfile, ...(value.profile as Partial<Profile>) } : defaultProfile
  const legacyContributions = Array.isArray(value.contributions) ? value.contributions as Array<Contribution & { alreadyPaid?: boolean; alreadyReflected?: boolean; includeInAnalytics?: boolean; transactionId?: string }> : []
  const contributions = legacyContributions.map((item) => {
    const contributionDate = item.contributionDate ?? item.date
    const historical = item.alreadyPaid === true && (item.alreadyReflected === true || !(item.sourceAccountId ?? item.accountId))
    const deducted = item.alreadyPaid === true && item.alreadyReflected !== true && Boolean(item.accountId)
    return {
      ...item,
      contributionDate,
      date: contributionDate,
      sourceAccountId: item.sourceAccountId ?? item.accountId,
      status: item.status ?? (item.alreadyPaid ? 'paid' : contributionDate > localDate() ? 'scheduled' : 'pending'),
      balanceEffect: item.balanceEffect ?? (historical ? 'historical_no_deduction' : deducted ? 'deducted' : 'none'),
      includeInExpenseAnalytics: item.includeInExpenseAnalytics ?? item.includeInAnalytics ?? false,
      createdAt: item.createdAt ?? new Date().toISOString(),
      updatedAt: item.updatedAt ?? new Date().toISOString(),
      transactionId: item.transactionId ?? (deducted ? `contribution:${item.id}:payment` : undefined),
    }
  })
  for (const contribution of contributions) {
    if (contribution.balanceEffect !== 'deducted' || !contribution.sourceAccountId || transactions.some((entry) => entry.id === contribution.transactionId || entry.type === 'expense' && entry.contributionId === contribution.id)) continue
    transactions.push({ id: contribution.transactionId ?? `contribution:${contribution.id}:payment`, type: 'expense', amount: contribution.amount, date: contribution.contributionDate ?? contribution.date, category: 'Others', description: `Contribution: ${contribution.title}`, accountId: contribution.sourceAccountId, contributionId: contribution.id })
    report.push(`A payment ledger entry was restored for contribution “${contribution.title}” during migration.`)
  }
  const plannedSpending = Array.isArray(value.plannedSpending) ? value.plannedSpending as PlannedSpending[] : []
  const transfers = Array.isArray(value.transfers) ? value.transfers as Transfer[] : []
  const balanceAdjustments = Array.isArray(value.balanceAdjustments) ? value.balanceAdjustments as BalanceAdjustment[] : []

  return { transactions, budgets, goals, dailyBudgets, accounts, profile, contributions, plannedSpending, transfers, balanceAdjustments, migrationReport: [...(Array.isArray(value.migrationReport) ? value.migrationReport as string[] : []), ...report] }
}

/** Applies a contribution edit and its linked payment ledger entry atomically. */
function saveContribution(setState: StoreApi<FinanceState>['setState'], contribution: Contribution, deductNow: boolean, forcePayNow = false): { success: boolean; message: string } {
  let result: { success: boolean; message: string } = { success: false, message: 'Contribution could not be saved.' }
  setState((state) => {
    const existing = state.contributions.find((item) => item.id === contribution.id)
    const contributionDate = contribution.contributionDate ?? contribution.date
    const today = localDate()
    const oldPaymentId = existing?.transactionId ?? `contribution:${contribution.id}:payment`
    const transactions = state.transactions.filter((entry) => entry.id !== oldPaymentId && !(entry.type === 'expense' && entry.contributionId === contribution.id))
    const accountId = contribution.sourceAccountId ?? contribution.accountId
    const now = localDateTime()
    let status: Contribution['status']
    let balanceEffect: Contribution['balanceEffect']
    let paidAt: string | undefined
    let transactionId: string | undefined

    if (forcePayNow) {
      const account = state.accounts.find((item) => item.id === accountId && !item.archived)
      if (!account) {
        result = { success: false, message: 'Select an active source account to pay this contribution.' }
        return {}
      }
      const balance = accountBalance(account, transactions, state.transfers, state.contributions, state.balanceAdjustments)
      if (contribution.amount > balance) {
        result = { success: false, message: `The selected account has ${balance.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })} available, which is not enough for this contribution.` }
        return {}
      }
      status = 'paid'
      balanceEffect = 'deducted'
      paidAt = now
      transactionId = oldPaymentId
      transactions.unshift({ id: transactionId, type: 'expense', amount: contribution.amount, date: today, category: 'Others', description: `Contribution: ${contribution.title}`, accountId: account.id, contributionId: contribution.id })
    } else if (contributionDate < today) {
      status = 'paid'
      balanceEffect = 'historical_no_deduction'
      paidAt = existing?.balanceEffect === 'historical_no_deduction' ? existing.paidAt : undefined
    } else if (contributionDate > today) {
      status = 'scheduled'
      balanceEffect = 'none'
    } else if (deductNow) {
      const account = state.accounts.find((item) => item.id === accountId && !item.archived)
      if (!account) {
        result = { success: false, message: 'Select an active source account to deduct this contribution.' }
        return {}
      }
      const balance = accountBalance(account, transactions, state.transfers, state.contributions, state.balanceAdjustments)
      if (contribution.amount > balance) {
        result = { success: false, message: `The selected account has ${balance.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })} available, which is not enough for this contribution.` }
        return {}
      }
      status = 'paid'
      balanceEffect = 'deducted'
      paidAt = existing?.balanceEffect === 'deducted' ? existing.paidAt ?? now : now
      transactionId = oldPaymentId
      transactions.unshift({ id: transactionId, type: 'expense', amount: contribution.amount, date: today, category: 'Others', description: `Contribution: ${contribution.title}`, accountId: account.id, contributionId: contribution.id })
    } else {
      status = 'pending'
      balanceEffect = 'none'
    }

    const nextContribution: Contribution = {
      ...contribution,
      date: contributionDate,
      contributionDate,
      sourceAccountId: accountId,
      accountId,
      status,
      balanceEffect,
      includeInExpenseAnalytics: contribution.includeInExpenseAnalytics ?? contribution.includeInAnalytics ?? false,
      paidAt,
      transactionId,
      createdAt: existing?.createdAt ?? contribution.createdAt ?? now,
      updatedAt: now,
      alreadyPaid: status === 'paid',
      alreadyReflected: balanceEffect === 'historical_no_deduction',
      includeInAnalytics: contribution.includeInExpenseAnalytics ?? contribution.includeInAnalytics ?? false,
    }
    result = { success: true, message: status === 'paid' && balanceEffect === 'deducted' ? `Contribution paid. ${contribution.amount.toLocaleString('en-PH', { style: 'currency', currency: 'PHP' })} was deducted from ${state.accounts.find((item) => item.id === accountId)?.name} for ${contribution.title}.` : status === 'paid' ? 'Historical contribution recorded. Your current balance was not changed.' : status === 'scheduled' ? 'Contribution scheduled. No money was deducted.' : 'Contribution saved as pending. No money was deducted.' }
    return { transactions, contributions: existing ? state.contributions.map((item) => item.id === contribution.id ? nextContribution : item) : [nextContribution, ...state.contributions] }
  })
  return result
}

/** Creates a collision-resistant id for local records. */
function createId() {
  return globalThis.crypto?.randomUUID?.() ?? `record-${Date.now()}-${Math.random().toString(36).slice(2)}`
}

/** Updates or appends a transaction in persisted local state. */
function upsertTransaction(entry: Transaction) {
  useFinanceStore.setState((state) => {
    let accounts = state.accounts
    let accountId = entry.accountId
    if (entry.type !== 'saving' && !accountId) {
      let account = accounts.find((item) => !item.archived)
      if (!account) {
        account = { id: 'account-default-cash', name: 'Cash', institution: 'Cash', kind: 'Cash', openingBalance: 0, includeInTotal: true, archived: false, color: '#3ba7ff', icon: 'wallet', nickname: '' }
        accounts = [...accounts, account]
      }
      accountId = account.id
    }
    const nextEntry = { ...entry, ...(accountId ? { accountId } : {}) } as Transaction
    return { accounts, transactions: state.transactions.some((item) => item.id === nextEntry.id) ? state.transactions.map((item) => item.id === nextEntry.id ? nextEntry : item) : [nextEntry, ...state.transactions] }
  })
}

