      const linked = state.transactions.some((entry) => entry.accountId === id) || state.transfers.some((transfer) => transfer.sourceAccountId === id || transfer.destinationAccountId === id) || state.contributions.some((item) => item.accountId === id) || state.plannedSpending.some((item) => item.accountId === id)
